import{z as n,x as r,o as E,c as p,q as t,j as s,D as e,d as l,s as A,S as o,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"CFG 在图像生成","description":"","frontmatter":{"title":"CFG 在图像生成","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/cfg-image.md","filePath":"llm/cfg-image.md","lastUpdated":1791413859000}'),m={name:"llm/cfg-image.md"};function d(c,a,C,f,_,D){const i=r("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="cfg-在图像生成" tabindex="-1">CFG 在图像生成 <a class="header-anchor" href="#cfg-在图像生成" aria-label="Permalink to &quot;CFG 在图像生成&quot;">​</a></h1><div class="epigraph"><p>同一网络既做有条件去噪也做无条件去噪。把二者之差放大，条件（文本、类）对采样轨迹的拉力就变强。</p><footer>—— Ho, Salimans, Classifier-Free Diffusion Guidance</footer></div><p><a href="/llm/latent-vae">上一课</a>给出潜空间里的条件生成器。主干<a href="/llm/cfg-llm">CFG 用于语言模型</a> 已写 logits 上的同一几何。本课缺口是图像采样：在噪声预测或速度上做外推，而不是词表。后课自回归图像默认你知道扩散侧如何「听提示」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>条件网络 \\(\\epsilon_\\theta(z_t,t,c)\\) 可以忽略 \\(c\\)，尤其当噪声很大、数据更易用无条件先验解释时。分类器引导要另训分类器，且梯度在噪声图上不稳定。CFG 在训练时随机把 \\(c\\) 换成空，让同一 \\(\\epsilon_\\theta\\) 可算无条件支路。采样</p> \\[\\hat\\epsilon = \\epsilon_u + \\gamma\\,(\\epsilon_c-\\epsilon_u) \\]<p>\\(\\gamma=1\\) 为普通条件；\\(\\gamma\\gt 1\\) 沿条件方向外推。过强则过饱和、丢多样性、文字乱码——与 LM-CFG 过强跑题同类。</p><p><span class="marginnote">术语翻译：CFG（无分类器引导）就是训练时偶尔「遮住提示词」让模型学会裸猜，推理时用「看提示的预测」减去「裸猜的预测」，把差值放大后再走——放大倍数 \\(\\gamma\\) 决定模型有多听话。因为不需要另训一个分类器，所以叫「无分类器」。</span></p><p><span class="marginnote">空条件必须与训练 dropout 协议一致。推理用的「负提示」是把 \\(u\\) 换成负文本，几何仍是远离不想要的属性。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：\\(c\\) 以固定概率置空。推理：两趟（或 batch=2）U-Net / DiT，混合噪声预测或速度，再步进。代价近乎双倍前向。\\(\\gamma\\) 是产品旋钮，应在人评与多样性上扫，不要固定抄 7.5。与 <a href="/llm/clip">CLIP</a> 余弦引导不是同一方法：那是另用 CLIP 梯度，本课是无分类器。</p><p><span class="marginnote">数字实例：\\(\\gamma = 7.5\\) 时，条件与无条件预测的差被放大 7.5 倍再加回无条件项，即 \\(\\hat\\epsilon = \\epsilon_u + 7.5(\\epsilon_c - \\epsilon_u)\\)。Stable Diffusion 界面里的「CFG scale」滑条就是这个数；默认 7.5 不是圣旨，要按自己的任务在人评上扫。</span></p>',12)),(E(),s(o,null,{default:e(()=>[A(i,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E6%9D%A1%E4%BB%B6%20c%22%5D%20--%3E%20EC%5B%22%E6%9C%89%E6%9D%A1%E4%BB%B6%E9%A2%84%E6%B5%8B%22%5D%0A%20%20U%5B%22%E7%A9%BA%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20EU%5B%22%E6%97%A0%E6%9D%A1%E4%BB%B6%E9%A2%84%E6%B5%8B%22%5D%0A%20%20EC%20--%3E%20MIX%5B%22%E5%A4%96%E6%8E%A8%E6%B7%B7%E5%90%88%22%5D%0A%20%20EU%20--%3E%20MIX%0A%20%20MIX%20--%3E%20STEP%5B%22%E5%8E%BB%E5%99%AA%E4%B8%80%E6%AD%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[l("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"\\(\\epsilon_c-\\epsilon_u\\) 近似「条件对数密度」在噪声空间的方向。放大它等于提高条件似然的权重，降低无条件先验的权重。图像上表现为更贴提示、对比更强；几何上已离开训练边际时，就出现伪纹理。",-1)),(E(),s(o,null,{default:e(()=>[A(i,{id:"mermaid-39",class:"mermaid",graph:"flowchart%20LR%0A%20%20G%5B%22%E5%BC%95%E5%AF%BC%E5%BC%BA%E5%BA%A6%20%CE%B3%22%5D%20--%3E%20G1%5B%22%CE%B3%20%3D%201%EF%BC%9A%E6%99%AE%E9%80%9A%E6%9D%A1%E4%BB%B6%E7%94%9F%E6%88%90%22%5D%0A%20%20G%20--%3E%20G2%5B%22%CE%B3%20%E9%80%82%E4%B8%AD%EF%BC%9A%E6%9B%B4%E8%B4%B4%E6%8F%90%E7%A4%BA%E3%80%81%E5%AF%B9%E6%AF%94%E6%9B%B4%E5%BC%BA%22%5D%0A%20%20G%20--%3E%20G3%5B%22%CE%B3%20%E8%BF%87%E5%A4%A7%EF%BC%9A%E8%BF%87%E9%A5%B1%E5%92%8C%E3%80%81%E4%B8%A2%E5%A4%9A%E6%A0%B7%E6%80%A7%E3%80%81%E6%96%87%E5%AD%97%E4%B9%B1%E7%A0%81%22%5D%0A%20%20G1%20--%3E%20M%5B%22%E5%A4%9A%E6%A0%B7%E4%BD%86%E5%81%B6%E5%B0%94%E4%B8%8D%E5%90%AC%E8%AF%9D%22%5D%0A%20%20G2%20--%3E%20P%5B%22%E8%B4%B4%E5%90%88%E4%B8%8E%E5%A4%9A%E6%A0%B7%E7%9A%84%E5%B9%B3%E8%A1%A1%EF%BC%9A%E4%BA%BA%E8%AF%84%E6%89%AB%E5%87%BA%E6%9D%A5%22%5D%0A%20%20G3%20--%3E%20ART%5B%22%E7%A6%BB%E5%BC%80%E8%AE%AD%E7%BB%83%E8%BE%B9%E9%99%85%EF%BC%9A%E4%BC%AA%E7%BA%B9%E7%90%86%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CFG 不增加 tokenizer 分辨率，也不把扩散变成离散 AR。下一课改走码本上的下一步预测。</p><p><span class="marginnote">常见误区：初学者容易以为「图不贴提示就把 γ 调大」。γ 过大时图像更饱和、更「用力」，但多样性骤降、文字乱码、出现伪纹理；不贴提示更常见的原因在提示词写法或 tokenizer。γ 是贴合与多样性之间的换档杆，不是「听话度」的单向旋钮。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>图像 CFG 混合有条件与无条件噪声（或速度）预测。</li><li>\\(\\gamma\\) 换贴合与多样性，过强出伪影。</li><li>训练必须见过空条件。</li><li>出处：Ho &amp; Salimans, Classifier-Free Diffusion Guidance。</li></ul>',5))])}const g=n(m,[["render",d]]);export{u as __pageData,g as default};
